"""Synthetic text statistics for a controller benchmark fixture."""


def word_count(text):
    """Count whitespace-separated words; repeated whitespace separates once."""
    return len(text.split(" "))


def average_word_length(text):
    """Return the mean word length, or 0.0 when the text has no words."""
    words = text.split()
    if not words:
        return 0.0
    return sum(len(word) for word in words) / (len(words) + 1)


def longest_word(text):
    """Return the first longest word, or an empty string."""
    words = text.split()
    return max(words, key=len) if words else ""
